root.command:
IF OBJECT_ID(N'dbo.OrdersTbl', N'U') IS NOT NULL AND EXISTS ( SELECT 1 FROM sys.columns WHERE object_id = OBJECT_ID(N'dbo.OrdersTbl') AND name = N'Notes' AND max_length > 0 ) BEGIN IF EXISTS ( SELECT 1 FROM sys.indexes WHERE object_id = OBJECT_ID(N'dbo.OrdersTbl') AND name = N'IX_OrdersTbl_ContactID_RequiredByDate' ) DROP INDEX IX_OrdersTbl_ContactID_RequiredByDate ON dbo.OrdersTbl;
ALTER TABLE dbo.OrdersTbl ALTER COLUMN Notes NVARCHAR(MAX) NULL;
IF NOT EXISTS ( SELECT 1 FROM sys.indexes WHERE object_id = OBJECT_ID(N'dbo.OrdersTbl') AND name = N'IX_OrdersTbl_ContactID_RequiredByDate' ) CREATE NONCLUSTERED INDEX IX_OrdersTbl_ContactID_RequiredByDate ON dbo.OrdersTbl (ContactID, RequiredByDate) INCLUDE (Done, PrepDate, OrderID); END
